CREATE COLUMN TABLE "TEST_AP"."OTWS" ("AbsEntry" SMALLINT CS_INT NOT NULL , "TwsName" NVARCHAR(64), "TwsURL" NCLOB MEMORY THRESHOLD 1000, "TwsDescrip" NVARCHAR(200), "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OTWS_TWSNAME" ON "TEST_AP"."OTWS" ( "TwsName" ASC )